import Foundation

/// The bundled offline puzzle set: 6,000 Lichess puzzles (CC0), 300 per 100-point rating
/// band from 400 to 2399, spread over themes. Generated by scripts/gen-puzzles.sh.
public enum PuzzleBank {
    /// Practice themes offered as chips, in display order (Lichess theme keys).
    public static let practiceThemes: [String] = [
        "mateIn1", "mateIn2", "mateIn3", "fork", "pin", "skewer", "hangingPiece",
        "discoveredAttack", "backRankMate", "endgame", "opening",
    ]

    public static let ratingRange = 400...2400

    public static func title(forTheme theme: String) -> String {
        switch theme {
        case "mateIn1": "Mate in 1"
        case "mateIn2": "Mate in 2"
        case "mateIn3": "Mate in 3"
        case "fork": "Fork"
        case "pin": "Pin"
        case "skewer": "Skewer"
        case "hangingPiece": "Hanging piece"
        case "discoveredAttack": "Discovered attack"
        case "backRankMate": "Back rank"
        case "capturingDefender": "Remove the defender"
        case "endgame": "Endgame"
        case "opening": "Opening"
        case "middlegame": "Middlegame"
        default: theme
        }
    }

    /// Every bundled puzzle, sorted by rating. Loaded on first use.
    public static let all: [Puzzle] = {
        guard let url = Bundle.module.url(forResource: "puzzles", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let rows = try? JSONDecoder().decode([Row].self, from: data) else {
            assertionFailure("PuzzleBank: puzzles.json missing or undecodable")
            return []
        }
        return rows.map(\.puzzle).sorted { ($0.rating, $0.id) < ($1.rating, $1.id) }
    }()

    private static let byId: [String: Puzzle] = Dictionary(all.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })

    public static func puzzle(id: String) -> Puzzle? { byId[id] }

    /// Ratings within ±100 of `rating`, clamped to the bank's range.
    public static func band(around rating: Int) -> Range<Int> {
        let center = min(max(rating, ratingRange.lowerBound + 100), ratingRange.upperBound - 100)
        return (center - 100)..<(center + 100)
    }

    /// Puzzles rated in `band`, optionally with `theme`, minus `excluding`; ordered by a
    /// stable shuffle so consecutive picks vary in theme and rating.
    public static func puzzles(band: Range<Int>, theme: String? = nil, excluding: Set<String> = []) -> [Puzzle] {
        all.filter {
            band.contains($0.rating) && !excluding.contains($0.id)
                && (theme.map($0.themes.contains) ?? true)
        }
        .sorted { stableHash($0.id) < stableHash($1.id) }
    }

    /// Lichess themes that train a weakness found in the user's games.
    public static func themes(for motif: Motif) -> [String] {
        switch motif {
        case .hangingPiece: ["hangingPiece"]
        case .allowedFork: ["fork"]
        case .missedMate, .allowedMate: ["mateIn1", "mateIn2"]
        case .missedCapture: ["hangingPiece", "capturingDefender"]
        case .openingPrinciple: ["opening"]
        }
    }

    /// Puzzles that train `motif`, near `rating`.
    public static func forWeakness(_ motif: Motif, rating: Int = PlayerProfile.defaultRating,
                                   excluding: Set<String> = []) -> [Puzzle] {
        let themes = Set(themes(for: motif))
        let near = band(around: rating)
        let wide = (near.lowerBound - 200)..<(near.upperBound + 200)
        return all.filter { wide.contains($0.rating) && !excluding.contains($0.id) && !themes.isDisjoint(with: $0.themes) }
            .sorted { (abs($0.rating - rating), stableHash($0.id)) < (abs($1.rating - rating), stableHash($1.id)) }
    }

    /// Ratings the daily puzzle is drawn from: a beginner app's daily should be solvable.
    public static let dailyBand = 600..<1500

    /// The puzzle of the day: a deterministic pick by the calendar date (web `daily.ts`:
    /// 31-hash of "yyyy-MM-dd" modulo the pool), from `dailyBand`.
    public static func daily(for date: Date, calendar: Calendar = .current) -> Puzzle? {
        let pool = all.filter { dailyBand.contains($0.rating) }
        guard !pool.isEmpty else { return nil }
        return pool[Int(hashString(dayKey(date, calendar: calendar))) % pool.count]
    }

    public static func dayKey(_ date: Date, calendar: Calendar = .current) -> String {
        let c = calendar.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
    }

    /// Port of `hashStr` in daily.ts: h = h * 31 + code, wrapped to Int32, then abs.
    static func hashString(_ s: String) -> UInt32 {
        var h: Int32 = 0
        for unit in s.utf16 { h = h &* 31 &+ Int32(unit) }
        return h.magnitude
    }

    private static func stableHash(_ s: String) -> UInt32 {
        var h: UInt32 = 2_166_136_261
        for b in s.utf8 { h = (h ^ UInt32(b)) &* 16_777_619 }
        return h
    }

    /// One row of puzzles.json: [id, fen, "uci uci …", rating, "theme theme …"].
    private struct Row: Decodable {
        let puzzle: Puzzle

        init(from decoder: any Decoder) throws {
            var c = try decoder.unkeyedContainer()
            let id = try c.decode(String.self)
            let fen = try c.decode(String.self)
            let moves = try c.decode(String.self).split(separator: " ").map(String.init)
            let rating = try c.decode(Int.self)
            let themes = try c.decode(String.self).split(separator: " ").map(String.init)
            puzzle = Puzzle(id: id, fen: fen, moves: moves, rating: rating, themes: themes)
        }
    }
}
